using STOREEX.Models; using System; using System.Linq; using System.Web.Mvc;
namespace STOREEX.Controllers { [Authorize] public class WarehousesController:Controller { private readonly StoreexDb db=new StoreexDb(); private const int CompanyId=1; public ActionResult Index(){return View(db.Warehouses.Where(x=>x.CompanyId==CompanyId).OrderByDescending(x=>x.IsMain).ThenBy(x=>x.Name).ToList());} [HttpPost,ValidateAntiForgeryToken] public ActionResult Save(Warehouse m){if(!ModelState.IsValid)return View("Index",db.Warehouses.Where(x=>x.CompanyId==CompanyId).ToList());if(m.Id==0){m.CompanyId=CompanyId;m.CreatedAt=DateTime.UtcNow;m.IsActive=true;db.Warehouses.Add(m);}else{var x=db.Warehouses.SingleOrDefault(z=>z.Id==m.Id&&z.CompanyId==CompanyId);if(x==null)return HttpNotFound();x.Name=m.Name;x.Code=m.Code;x.Address=m.Address;x.City=m.City;x.Phone=m.Phone;x.IsMain=m.IsMain;x.IsActive=m.IsActive;}db.SaveChanges();return RedirectToAction("Index");} public ActionResult Stock(int id){var w=db.Warehouses.SingleOrDefault(x=>x.Id==id&&x.CompanyId==CompanyId);if(w==null)return HttpNotFound();ViewBag.Warehouse=w;return View(db.WarehouseStocks.Where(x=>x.WarehouseId==id&&x.Product.CompanyId==CompanyId).OrderBy(x=>x.Product.Name).ToList());} protected override void Dispose(bool d){if(d)db.Dispose();base.Dispose(d);}}}